namespace sv_9dc49a2e623443f8b5606e44eaa22663;

/// <summary>
/// Placeholder implementation of IApplicationService for development/testing.
/// Replace with a real implementation that persists data.
/// </summary>
public class DummyApplicationService : IApplicationService
{
    private static int _nextId = 1000;

